DATA_DIR = Path(__file__).parent
KML_NS = {"k": "http://www.opengis.net/kml/2.2"}


def read_kmz(filename: str) -> dict:
    """Read regular KMZ archives and KML files mistakenly named .kmz."""
    path = DATA_DIR / filename
    raw = path.read_bytes()
    if raw[:2] == b"PK":
        with zipfile.ZipFile(path) as archive:
            kml_name = next(n for n in archive.namelist() if n.lower().endswith(".kml"))
            raw = archive.read(kml_name)
    # These two concession files declare UTF-8 but contain legacy Windows-1252 bytes.
    try:
        xml = raw.decode("utf-8")
        ET.fromstring(xml)  # Some malformed exports declare UTF-8 but contain cp1252 bytes.
    except (UnicodeDecodeError, ET.ParseError):
        xml = raw.decode("cp1252")
    root = ET.fromstring(xml)
    styles = {s.get("id"): s for s in root.findall(".//k:Document/k:Style", KML_NS)}
    style_maps = {}
    for style_map in root.findall(".//k:Document/k:StyleMap", KML_NS):
        for pair in style_map.findall("k:Pair", KML_NS):
            if pair.findtext("k:key", default="", namespaces=KML_NS) == "normal":
                style_maps[style_map.get("id")] = pair.findtext("k:styleUrl", default="", namespaces=KML_NS).lstrip("#")
    out = {"groups": {}, "polygons": []}

    def coordinates(node):
        text = node.findtext("k:coordinates", default="", namespaces=KML_NS)
        result = []
        for pair in text.split():
            bits = pair.split(",")
            if len(bits) >= 2:
                try:
                    result.append([float(bits[0]), float(bits[1])])
                except ValueError:
                    continue
        return result

    def group_for(placemark):
        folders = []
        parent = parents.get(placemark)
        while parent is not None:
            if parent.tag.rsplit("}", 1)[-1] == "Folder":
                folders.append(parent.findtext("k:name", default="", namespaces=KML_NS))
            parent = parents.get(parent)
        folders.reverse()
        return folders[1] if len(folders) > 1 else (folders[0] if folders else "Red eléctrica")

    parents = {child: parent for parent in root.iter() for child in parent}
    for placemark in root.findall(".//k:Placemark", KML_NS):
        name = placemark.findtext("k:name", default="", namespaces=KML_NS)
        description = placemark.findtext("k:description", default="", namespaces=KML_NS)
        style_id = placemark.findtext("k:styleUrl", default="", namespaces=KML_NS).lstrip("#")
        style_id = style_maps.get(style_id, style_id)
        style = styles.get(style_id)
        icon = style.findtext("k:IconStyle/k:Icon/k:href", default="", namespaces=KML_NS) if style is not None else ""
        point_color = style.findtext("k:IconStyle/k:color", default="", namespaces=KML_NS) if style is not None else ""
        line_color = style.findtext("k:LineStyle/k:color", default="", namespaces=KML_NS) if style is not None else ""
        if not point_color:
            point_color = placemark.findtext("k:Style/k:IconStyle/k:color", default="", namespaces=KML_NS)
        if not line_color:
            line_color = placemark.findtext("k:Style/k:LineStyle/k:color", default="", namespaces=KML_NS)

        def css_color(kml_color, fallback):
            value = (kml_color or "").strip().lstrip("#")
            if len(value) == 8:
                return "#" + value[6:8] + value[4:6] + value[2:4]
            return fallback

        group = group_for(placemark)
        bucket = out["groups"].setdefault(group, {"points": [], "lines": []})
        fallback = {"Postes": "#ffca28", "Equipos": "#26a69a", "Subestaciones": "#ab47bc", "Redes MT": "#2962ff", "Red BT": "#fdd835"}.get(group, "#607d8b")
        attributes = {}
        for data in placemark.findall(".//k:Data", KML_NS):
            value = data.findtext("k:value", default="", namespaces=KML_NS)
            if data.get("name") and value:
                attributes[data.get("name")] = value
        for data in placemark.findall(".//k:SimpleData", KML_NS):
            if data.get("name") and data.text:
                attributes[data.get("name")] = data.text.strip()
        props = {"name": name, "description": description, "icon": icon,
                 "attributes": attributes, "color": css_color(point_color, fallback), "line_color": css_color(line_color, fallback)}
        for point in placemark.findall(".//k:Point", KML_NS):
            c = coordinates(point)
            if c:
                bucket["points"].append({**props, "coordinates": c[0]})
        for line in placemark.findall(".//k:LineString", KML_NS):
            c = coordinates(line)
            if len(c) > 1:
                bucket["lines"].append({**props, "coordinates": c})
        for polygon in placemark.findall(".//k:Polygon", KML_NS):
            rings = [coordinates(r) for r in polygon.findall(".//k:LinearRing", KML_NS)]
            rings = [r for r in rings if len(r) > 2]
            if rings:
                out["polygons"].append({**props, "coordinates": rings})
    return out


def split_centrality_cameras(centrality: dict) -> tuple[list[dict], list[dict]]:
    """Separate .C camera records and add only verified same-code pole links."""
    tagged_points = [
        {**item, "centrality_group": group_name}
        for group_name, group in centrality["groups"].items()
        for item in group["points"]
    ]
    regular_points = []
    camera_points = []
    poles_by_code = {}
    for item in tagged_points:
        attrs = item.get("attributes", {})
        code = str(attrs.get("IDENTIFICADOR_VNR") or item.get("name") or "").strip()
        if not code.upper().endswith(".C") and item.get("centrality_group") == "Postes":
            poles_by_code[code.upper()] = item

    for item in tagged_points:
        attrs = dict(item.get("attributes", {}))
        code = str(attrs.get("IDENTIFICADOR_VNR") or item.get("name") or "").strip()
        if not code.upper().endswith(".C"):
            regular_points.append(item)
            continue
        base_code = code[:-2].strip()
        pole = poles_by_code.get(base_code.upper())
        if pole:
            try:
                camera_x, camera_y = float(attrs["X"]), float(attrs["Y"])
                pole_attrs = pole.get("attributes", {})
                pole_x, pole_y = float(pole_attrs["X"]), float(pole_attrs["Y"])
                if ((camera_x - pole_x) ** 2 + (camera_y - pole_y) ** 2) ** 0.5 <= 25:
                    attrs["POSTE_ASOCIADO"] = base_code
                    for key in ("SUBESTACION", "SE", "ALIMENTADOR", "ALIMENTADOR_ID"):
                        if not attrs.get(key) and pole_attrs.get(key):
                            attrs[key] = pole_attrs[key]
            except (KeyError, TypeError, ValueError):
                pass
        camera_points.append({**item, "attributes": attrs, "centrality_group": "Camaras"})
    return regular_points, camera_points


def enrich_post_network(dataset: dict, catalog: dict) -> None:
    """Add feeder/substation data only through exact official post IDs or plates."""
    records = catalog.get("records", {})
    codes = catalog.get("codes", {})
    for group_name, group in dataset["groups"].items():
        if group_name != "Postes":
            continue
        for item in group["points"]:
            attrs = dict(item.get("attributes", {}))
            post_id = str(attrs.get("POSTE_ID") or "").strip()
            code = str(attrs.get("IDENTIFICADOR_VNR") or item.get("name") or "").strip().upper()
            info = records.get(post_id) or records.get(codes.get(code, ""))
            if not info:
                continue
            if info.get("a") and not attrs.get("ALIMENTADOR_ID"):
                attrs["ALIMENTADOR_ID"] = info["a"]
            if info.get("s") and not (attrs.get("SUBESTACION") or attrs.get("SE")):
                attrs["SUBESTACION"] = info["s"]
            item["attributes"] = attrs


NETWORK = "Punta Arenas.kmz"
CONCESSION_LT = "concesiones2025v3 corregidas menor a 15.kmz"
CONCESSION_GE = "concesiones2025v3 GEO superior a 14.kmz"
PERIURBANO = "Periurbano completo.kmz"; CENTRALITY = "Punta Arenas_v2.kmz"
CAMERA_CATALOG = "cameras_catalog.json"
POST_NETWORK_CATALOG = "post_network_catalog.json"

@st.cache_resource(show_spinner="Preparando las capas del mapa…")
def build_layers_json() -> str:
    network = read_kmz(NETWORK)
    concession_lt = read_kmz(CONCESSION_LT)
    concession_ge = read_kmz(CONCESSION_GE)
    periurbano = read_kmz(PERIURBANO)
    centrality = read_kmz(CENTRALITY)
    post_network_catalog = json.loads((DATA_DIR / POST_NETWORK_CATALOG).read_text(encoding="utf-8"))
    enrich_post_network(network, post_network_catalog)
    enrich_post_network(centrality, post_network_catalog)
    centrality_points, camera_points = split_centrality_cameras(centrality)
    camera_catalog = json.loads((DATA_DIR / CAMERA_CATALOG).read_text(encoding="utf-8"))
    cameras_by_code = {
        str(item.get("attributes", {}).get("IDENTIFICADOR_VNR") or item.get("name") or "").strip().upper(): item
        for item in camera_points
    }
    for catalog_item in camera_catalog:
        code = str(catalog_item.get("attributes", {}).get("IDENTIFICADOR_VNR") or catalog_item.get("name") or "").strip().upper()
        if code in cameras_by_code:
            existing = cameras_by_code[code]
            existing["attributes"] = {**existing.get("attributes", {}), **catalog_item.get("attributes", {})}
        else:
            new_item = {**catalog_item, "centrality_group": "Camaras", "description": "Catálogo de nodos EDELMAG"}
            camera_points.append(new_item)
            cameras_by_code[code] = new_item
    layers = [
        {"id": "network-" + str(i), "name": name,
         "color": {"Equipos": "#26a69a", "Postes": "#ffca28", "Subestaciones": "#ab47bc", "Redes MT": "#ff3030", "Red BT": "#1646ff"}.get(name, "#607d8b"),
         "data": {"points": group["points"], "lines": group["lines"], "polygons": []}}
        for i, (name, group) in enumerate(network["groups"].items())
        if group["points"] or group["lines"]
    ]
    layers += [
        {"id": "lt15", "name": "Concesión menor a 15", "color": "#26c6da",
         "data": {"points": [], "lines": [], "polygons": concession_lt["polygons"]}},
        {"id": "ge14", "name": "Concesión GEO superior a 14", "color": "#ff7043",
         "data": {"points": [], "lines": [], "polygons": concession_ge["polygons"]}},
    ]

    layers += [{
        "id": "periurbano",
        "name": "Periurbano completo",
        "color": "#ffd21f",
        "data": {
            "points": [{**item, "municipal_group": group_name} for group_name, group in periurbano["groups"].items() for item in group["points"]],
            "lines": [item for group in periurbano["groups"].values() for item in group["lines"]],
            "polygons": periurbano["polygons"],
        },
    }]



    # Keep raw feature attributes in the browser search index; Leaflet renders the
    # dense electrical network through a shared Canvas renderer.
    layers += [{"id":"centrality","name":"Centrality","color":"#00a6a6","data":{"points":centrality_points,"lines":[item for group in centrality["groups"].values() for item in group["lines"]],"polygons":centrality["polygons"]}}]
    layers += [{"id":"cameras","name":"Cámaras","color":"#3949ab","data":{"points":camera_points,"lines":[],"polygons":[]}}]
    layers_bytes = json.dumps(layers, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return base64.b64encode(gzip.compress(layers_bytes, compresslevel=6)).decode("ascii")

try:
    layers_json = build_layers_json()
except Exception as exc:
    st.error(f"No se pudieron preparar las capas: {exc}")
    st.stop()
